"""Private, immutable object storage. Keys are generated by the server, never filenames."""

import hashlib
import os
import re
import shutil
import tempfile
from pathlib import Path
from typing import BinaryIO, Protocol

import boto3
from botocore.config import Config
from botocore.exceptions import BotoCoreError, ClientError

from app.config import Settings

KEY = re.compile(r"[0-9a-f]{32}/[0-9a-f]{32}\Z")


def validate_key(key: str):
    if not KEY.fullmatch(key):
        raise ValueError("Invalid storage key")


class ObjectStorage(Protocol):
    def put(self, key: str, source: BinaryIO, sha256: str): ...
    def get(self, key: str, limit: int) -> bytes: ...
    def delete(self, key: str): ...


class LocalStorage:
    def __init__(self, root: Path):
        self.root = root.resolve()

    def path(self, key: str) -> Path:
        validate_key(key)
        path = (self.root / key).resolve()
        if not path.is_relative_to(self.root):
            raise ValueError("Storage path escapes its root")
        return path

    def put(self, key: str, source: BinaryIO, sha256: str):
        path = self.path(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        temp = None
        try:
            with tempfile.NamedTemporaryFile(
                dir=path.parent,
                prefix=f".{path.name}.",
                suffix=".tmp",
                delete=False,
            ) as target:
                temp = Path(target.name)
                source.seek(0)
                shutil.copyfileobj(source, target, length=65536)
                target.flush()
                os.fsync(target.fileno())
            with temp.open("rb") as written:
                if hashlib.file_digest(written, "sha256").hexdigest() != sha256:
                    raise OSError("Object checksum mismatch")
            try:
                os.link(temp, path)
            except FileExistsError:
                with path.open("rb") as existing:
                    if hashlib.file_digest(existing, "sha256").hexdigest() != sha256:
                        raise OSError("Immutable object differs") from None
            if os.name != "nt":
                fd = os.open(path.parent, os.O_RDONLY)
                try:
                    os.fsync(fd)
                finally:
                    os.close(fd)
        finally:
            if temp is not None:
                temp.unlink(missing_ok=True)

    def get(self, key: str, limit: int) -> bytes:
        with self.path(key).open("rb") as source:
            data = source.read(limit + 1)
        if len(data) > limit:
            raise OSError("Stored object exceeds its declared size")
        return data

    def delete(self, key: str):
        path = self.path(key)
        path.unlink(missing_ok=True)
        # Any interrupted local writes for this reserved key are now safe to discard.
        for temp in path.parent.glob(f".{path.name}.*.tmp"):
            if temp.is_file() and not temp.is_symlink():
                temp.unlink(missing_ok=True)


class S3Storage:
    def __init__(self, settings: Settings):
        self.bucket = settings.s3_bucket
        self.client = boto3.client(
            "s3",
            region_name=settings.s3_region,
            endpoint_url=settings.s3_endpoint_url,
            aws_access_key_id=(
                settings.s3_access_key.get_secret_value() if settings.s3_access_key else None
            ),
            aws_secret_access_key=(
                settings.s3_secret_key.get_secret_value() if settings.s3_secret_key else None
            ),
            config=Config(
                connect_timeout=3,
                read_timeout=5,
                retries={"total_max_attempts": 2},
                s3={"addressing_style": "path"},
            ),
        )

    def put(self, key: str, source: BinaryIO, sha256: str):
        validate_key(key)
        source.seek(0)
        size = source.seek(0, os.SEEK_END)
        source.seek(0)
        if hashlib.file_digest(source, "sha256").hexdigest() != sha256:
            raise OSError("Object checksum mismatch")
        source.seek(0)
        try:
            self.client.put_object(
                Bucket=self.bucket,
                Key=key,
                Body=source,
                IfNoneMatch="*",
                ContentType="application/octet-stream",
                Metadata={"sha256": sha256},
            )
        except ClientError as exc:
            if exc.response["ResponseMetadata"]["HTTPStatusCode"] != 412:
                raise OSError("Object write failed") from None
            if hashlib.sha256(self.get(key, size)).hexdigest() != sha256:
                raise OSError("Immutable object differs") from None
        except BotoCoreError:
            raise OSError("Object write failed") from None

    def get(self, key: str, limit: int) -> bytes:
        validate_key(key)
        try:
            response = self.client.get_object(Bucket=self.bucket, Key=key)
            with response["Body"] as body:
                data = body.read(limit + 1)
            if len(data) > limit:
                raise OSError("Stored object exceeds its declared size")
            return data
        except ClientError as exc:
            if exc.response["Error"]["Code"] in {"NoSuchKey", "404"}:
                raise FileNotFoundError("Object not found") from None
            raise OSError("Object read failed") from None
        except BotoCoreError:
            raise OSError("Object read failed") from None

    def delete(self, key: str):
        validate_key(key)
        try:
            self.client.delete_object(Bucket=self.bucket, Key=key)
        except (ClientError, BotoCoreError):
            raise OSError("Object removal failed") from None


def build_storage(settings: Settings) -> ObjectStorage:
    if settings.storage_backend == "s3":
        return S3Storage(settings)
    return LocalStorage(settings.blob_directory)
